      "claim": "Safinamide absolute bioavailability was 95.3% in the fed state, demonstrating that an orally absorbed amine-containing drug can maintain high F with food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Lumiracoxib, a halogenated arylacetic acid, had an absolute bioavailability of approximately 74%, supporting high F for the halogenated carboxylic acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Telmisartan absolute bioavailability was 57.4% at a 160 mg oral dose, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
